# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe Invoices::ReservationRequest do
  # The request is the only thing that carries the company across the reservation port, so a request
  # with no company is refused when it is built rather than left for an adapter to scope.
  it "refuses to build a reservation request without a company_id" do
    attributes = {
      invoice_id: 10, operation_id: SecureRandom.uuid, generation: 1, disposition: "active", entries: [1, 2]
    }

    expect { described_class.new(company_id: nil, **attributes) }.to raise_error(ArgumentError)

    request = described_class.new(company_id: 5, **attributes)
    expect(request.company_id).to eq(5)
    expect(request.invoice_id).to eq(10)
  end
end
